213	            if (object instanceof Consumer                 // Is there a consumer in that location?
214	                && object.getClass() == this.getClass()    // Is the consumer of the same type as this one?
215	                && ((Consumer) object).canBreed()          // Can that consumer breed?
216	                && ((Actor) object).getGender() != gender) // Is that consumer of the opposite sex?
217	            {
218	                return true; // We have found a valid mate.
219	            }
220	        }
221	        
222	        return false; // We didn't manage to find a valid mate.
223	    }
