262	     * Only the first live prey is eaten.
263	     * 
264	     * @return Where food was found, or null if it wasn't.
265	     */
266	    private Location findFood()
267	    {
268	        // Get adjacent locations:
269	        Field field;
270	        field = getField();
271	        List<Location> adjacentLocations = field.adjacentLocations(getLocation());
272	        
273	        Iterator<Location> it = adjacentLocations.iterator();
274	        
275	        while (it.hasNext())
276	        {
277	            Location where = it.next();
278	            Object object = field.getObjectAt(where);
279	            
280	            for (Class<? extends Actor> preyClass : prey)
281	            {   
282	                if (preyClass.isInstance(object))
283	                {   
284	                    Actor actor = (Actor) object;
285	                    
286	                    if (actor.getIsAlive())
287	                    {   
288	                        // If it's night, there is a probability of missing the prey:
289	                        if (TimeSystem.isNightTime())
